  'fx.det.lede.dette': 'structure',
  'fx.det.lede.dette.tip': "All borrowings contracted by the City to finance capital investment: bank loans, listed bonds, Caisse des Dépôts. Principal repayment comes from gross savings.",
  'fx.det.lede.c3': ', ',
  'fx.det.lede.regleor': "golden rule",
  'fx.det.lede.regleor.tip': "Accounting rule requiring local authorities to vote a balanced operating budget. Borrowing can only finance capital investment, never running costs.",
  'fx.det.lede.post': " of budgetary balance.",
  'fx.det.s03.kind.tip': "Snapshot of what the City owns and how it's financed at year-end. Assets (left) always equal liabilities (right) by accounting construction.",
