  'fx.det.stress.kind.tip': "Simulation of adverse scenarios (revenue drop, interest rate rise) to test the City's ability to repay its debt. Key indicator: debt payoff capacity in years.",
  'fx.det.s02.hero_cap.eq.tip': "Universal accounting formula: Assets − (Total debt + Provisions) = Equity. Equity measures the City's net wealth.",
