  'fx.tp.note': "Method: each figure = total City of Paris ÷ 2.13 M residents. These shares are accounting abstractions — the City does not bill you individually; its budget is a single pool fed by all its revenues (property tax, waste-collection tax, State grants, transfer taxes, etc.) and every euro received funds every expense proportionally. Source: City of Paris administrative accounts.",
