  'fx.foot.link.cities': 'For town halls',

  'fx.contact.c4.n': 'Cities',
  'fx.contact.c4.h': 'Your city',
  'fx.contact.c4.p': "You want this site for your city.",

  'fx.closing.title': "This site can exist for your city.",
  'fx.closing.text': "It is built from the data the city already publishes.",
  'fx.closing.cta': "For cities",

  'fx.cities.meta.title': "For town halls",
  'fx.cities.meta.desc': "Every French town already has its page, built from public data. With the town hall’s own data it shows more: Paris is the example.",
  'fx.cities.kicker': "— For town halls",
  'fx.cities.h1': "Your town already has its page.",
  'fx.cities.lede': "It is built from public data: the DGFiP accounts, the OFGL aggregates, public contracts, voted tax rates, the register of elected officials. It is refreshed every year, when those sources publish.",
  'fx.cities.find': "Find your town",
  'fx.cities.s01.kind': "Already online",
  'fx.cities.s01.title': "What it already shows",
  'fx.cities.s01.p1': "How much the town spends, what the money is for, what it builds, what it buys, the property tax, the debt. Every figure is set against the towns of the same size, and a neighbour, so you know whether it is large or small.",
  'fx.cities.s01.p2': "The page is public: anyone can check it, report an error to us, share a figure or compare two towns.",
  'fx.cities.s02.kind': "With your data",
  'fx.cities.s02.title': "What it becomes with your data",
  'fx.cities.s02.p1': "National data describes the accounts. It does not say who a grant goes to, what a worksite looks like, or what the swimming pool cost. That is what the town’s own data brings, and",
  'fx.cities.s02.paris': "Paris",
  'fx.cities.s02.p1_after': " shows what it looks like:",
  'fx.cities.s02.b1': "grants, recipient by recipient, year by year;",
  'fx.cities.s02.b2': "worksites, with their photo and their progress;",
  'fx.cities.s02.b3': "the voted budget, readable by public policy, as soon as it is voted;",
  'fx.cities.s02.b4': "places: what the city paid for the pool, the school, the stadium;",
  'fx.cities.s02.b5': "a question asked of the data in plain language — “how much does waste collection cost?” — with an answer that cites its figures.",
  'fx.cities.s02.p2': "For that we need your files. Nothing is installed on your side and we enter none of your software. We read the data, we put it online, we keep it up to date.",
  'fx.cities.s03.kind': "Write",
  'fx.cities.s03.title': "Tell us what is missing",
  'fx.cities.s03.p1': "We have been building this site since the spring and we need to understand how things work on your side. Three questions interest us:",
  'fx.cities.s03.q1': "what do you do today when a resident, a journalist or a councillor asks where the money goes?",
  'fx.cities.s03.q2': "what would you want your town’s page to show?",
  'fx.cities.s03.q3': "what do you have, in your files, that nobody sees?",
  'fx.cities.s03.p2': "Write to daniel@qipu.org with the name of the town.",
  'fx.cities.s03.btn': "Email daniel@qipu.org",
  'fx.contact.s02.kind': "Report",
  'fx.contact.s02.title.before': "Spotted an ",
  'fx.contact.s02.title.em': "error",
  'fx.contact.s02.title.after': "? Here's how to tell us.",
  'fx.contact.s02.sub': "Every confirmed correction is published on /corrections with its date, scope, and a link to the report.",
  'fx.contact.s02.step1.h': "1. Pinpoint precisely",
  'fx.contact.s02.step1.p': "Note the page URL, the affected section or panel, and the exact figure or phrase that's problematic.",
  'fx.contact.s02.step2.h': "2. Reference the official source",
  'fx.contact.s02.step2.p': "If you have a link to the dataset, accounting appendix, or publication that contradicts what we show, attach it. Not mandatory but speeds up verification.",
  'fx.contact.s02.step3.h': "3. Send the report",
  'fx.contact.s02.step3.p': "Use the public form — a few fields, 1 minute. Don't feel like it? Email daniel@qipu.org with the same details.",
  'fx.contact.s02.btn.issue': "Open the report form",
  'fx.contact.s02.btn.history': "View correction history",

