  'fx.sec.lieux.u.what_body': '{n} facilities everyone knows, chosen by us: pools, parks, theatres, museums, squares, markets, churches the City owns. It is a selection, and it grows. For each, what the Conseil de Paris decided and what the City paid.',
  'fx.sec.lieux.u.paid': 'Paid or ceiling: what is the difference?',
