  'fx.sec.subv.u.conc_body': 'The largest recipients are the City’s own operators: the social action centre, Paris Musées, the school funds, the social landlords. Their operating grant is voted every year and sits here, next to the aid to associations. The median is {median}: half of the grants are smaller.',
