  'db.disp.keyfigures.sources': 'Sources: Eurostat gov_10a_main, {sources}.',
  'db.disp.foot_cue': 'Zoom on social security',
  // ─ Zoom Sécu ─
  'db.secu.num': 'Social security — €{monthly}/month/inhabitant',
  'db.secu.name': 'Social security',
  'db.secu.amt': '€{monthly}/month of your contribution',
  'db.secu.deck1': 'Four mutualised branches: {b}health{/b}, {b}pensions{/b}, {b}family{/b}, {b}unemployment{/b}.',
  'db.secu.deck2': 'Most of it funds healthcare and pensions.',
  'db.secu.source': 'Source: PLFSS 2025',
  'db.secu.retraite_sub': 'Covers private-sector employees + complementary schemes (AGIRC-ARRCO) + local/hospital civil servants (CNRACL) + self-employed (CIPAV, MSA…). State civil servants\' pensions are paid directly by the State via CAS Pensions — see State panel below.',
  'db.secu.foot_cue': 'Zoom on the State',
  // ─ Zoom État ─
  'db.etat.num': 'Central government — €{monthly}/month/inhabitant',
  'db.etat.name': 'Central government and operators',
  'db.etat.amt': '€{monthly}/month of your contribution',
  'db.etat.deck1': 'The State budget funds {b}33 PLF missions{/b}, grouped here into {b}10 categories{/b}: education, defence, security, justice, solidarity, labour, ecology, culture, public debt — plus an {b}Other{/b} bucket (agriculture, Overseas territories, foreign affairs, economy, veterans).',
  'db.etat.deck2': 'Central government and its operators carry the sovereign missions (defence, security, justice, foreign affairs) and national education — the most visible budget items.',
  'db.etat.source': 'Source: LFI 2025',
  'db.etat.scope_note': 'Method note · The 33 PLF missions total {plf_total} (≈ 66 % of the Eurostat S1311 perimeter: {s1311_total}). The ~{delta} difference covers State operators (ODAC), EU transfers, and special pension schemes not attached to a mission. These amounts are included in your overall State share, but their thematic attribution is not publicly published in the PLF — so the sum of bars above does not equal your {monthly} €/mo State.',
  'db.etat.bucket.autres.name': 'Other spending (outside PLF missions)',
  'db.etat.bucket.autres.sub': 'ODAC (universities, France Compétences, ANR, France Travail…) · Special accounts (military pensions, loans) · Annex budgets (official publications, air-traffic control) · Special schemes not tied to a PLF mission',
  'db.etat.foot_cue': 'Zoom on local',
  // ─ Zoom Local ─
  'db.local.kind': 'Local level',
  'db.local.num': 'Local authorities — €{monthly}/month/inhabitant',
  'db.local.title': 'Region · Department · Municipal block',
  'db.local.subtitle': 'Estimate of the share of your levies that funds local budgets (weighted by €/resident vs national average).',
  'db.local.amt': '€{monthly}/month of your contribution',
  'db.local.deck1': 'On average, France spends €{monthly}/month/inhabitant on local authorities, split across three levels: {b}municipal block{/b} (communes + intercommunalities), {b}departments{/b}, {b}regions{/b}.',
  'db.local.deck2': 'The municipal block carries the services {em}most visible day-to-day{/em}: roads, primary schools, urban transport, cleanliness, sports facilities.',
  'db.local.source': 'Source: OFGL 2024 (weighted €/resident spending)',
  'db.local.cta': 'See the full {city} page',
  'db.local.foot_cue': 'Summary',
  'db.local.body': '{city} spends on average €{eurhab} per resident per year. From your levies, that\'s about €{monthly} per month funding local services.',
  // ─ Personalized labels by selected commune (Fix 2 §05) ─
  'db.local.bloc_default': 'Cities and intercommunalities (municipal block)',
