  'db.macro_micro.deck': 'The calculation above relies on Eurostat and INSEE aggregates. For Paris, the micro level is publicly accessible: grant recipients, public procurement contractors, investment destinations.',
  'db.macro_micro.card.budget.label': 'Overview',
