  'us.sf.payroll.hook.body': 'The City paid <b>{ot}</b> in overtime in FY{fy} — <b>{share}</b> of all compensation, against {share0} in FY{y0}. Police overtime alone went from {ot0} to {ot1} while the department went from {n0} to {n1} people. That year, <b>{counter}</b> employees were paid more in overtime than in salary.',
