  'us.sf.thecity.scrub.no_volume': 'No volume for {year} has been read yet, so the record has nothing to say about that year.',
  'us.sf.thecity.scrub.past_sweep': 'The last street acceptance in the volumes read so far lands in {year}. The buildings after it come from the assessor’s roll, which is why the city keeps filling in while the record stays empty.',
  'us.sf.thecity.scrub.trees': 'The earliest planting date anywhere in the street tree file is {year}, so the {n} trees it does not date are not drawn before then.',
  'us.sf.thecity.scrub.undated': '{n} of the {of} buildings, streets, trees and named places on this map carry no date of their own in any published file. {e} of them are drawn in every year; the rest arrive on a year borrowed from something beside them — a street’s, a block’s — or are held off the dated map altogether.',
  'us.sf.thecity.map.help_years': 'Drag the year bar under the map to rebuild the city to any year from 1906 on, or press play to run the century.',
