  'us.sf.thecity.map.help_keys': 'Keyboard: arrows move, + and − zoom, Home returns to the whole city, Enter opens whatever is in the middle of the frame.',
  'us.sf.thecity.margin.head': 'The record',
  'us.sf.thecity.margin.lede': 'Click anywhere on the map to see what the city decided there. Every line links to the page of the scan it was read from.',
  'us.sf.thecity.margin.decisions': 'Decisions on the map',
  'us.sf.thecity.margin.years': 'Years covered',
  'us.sf.thecity.margin.blocks': 'Places with something',
  'us.sf.thecity.note.line': 'Every building here is one San Francisco publishes, drawn from the data. Only what is standing today is in the record.',
  'us.sf.thecity.note.more': 'How this map is made',
  'us.sf.thecity.note.shapes.title': 'What you are looking at',
  'us.sf.thecity.note.shapes': 'The outlines are the city’s own building footprints, each drawn at the height measured over it from the air. The roof colours are read off aerial photography. The ground underneath is the city’s elevation data, and the coastline, the streets and the block outlines are published files as well.',
  'us.sf.thecity.note.closest': 'The closest view stops where the file stops. Footprints are published on a one-metre grid, so at Street one metre is about two and a half pixels on screen. That closeness is the same on a phone as on a desktop; a wider window fits more of the city into the frame, drawn no finer.',
  'us.sf.thecity.note.standing.title': 'What is missing',
  'us.sf.thecity.note.standing': 'The city publishes what is standing today, so a building that was pulled down is in no file and can appear in no year. The Western Addition thins out towards 1960 on this map because the city cleared it, and what it cleared was never here to draw.',
  'us.sf.thecity.note.year': 'A building is drawn from the year the assessor gives it, in the shape it has now. Later additions and conversions are folded into that shape.',
  'us.sf.thecity.note.record.title': 'The decisions',
  'us.sf.thecity.note.record': 'They come from two record systems, {span} in all. {avol} scanned volumes of the Board of Supervisors’ minute books and the department annual reports, {aspan}, held by the Internet Archive; and {cfiles} minutes files the Clerk of the Board posts on sfbos.org, {cspan}, which no library holds. {placed} of them land somewhere on this map. {street} name only a street the block fronts, and the panel keeps those apart from the ones that name the block itself. Another {unplaced} name no place we could resolve, and are drawn nowhere at all.',
  'us.sf.thecity.note.accuracy': 'Placement was checked against the {key} decisions that print their own block number, hiding that sentence from the join and scoring what it did without it — {n} of them were placed precisely enough to score, and {exact}% landed on the block the record named.',
  'us.sf.thecity.note.sources.title': 'Where this comes from',
  'us.sf.thecity.note.sources': 'None of it is our own survey. San Francisco’s open data portal publishes the buildings, the blocks, the streets and the ground they stand on. The scanned volumes are held by the Internet Archive, the minutes since 2016 are posted by the Clerk of the Board on sfbos.org, and the aerial photography the roof colours are read from is Esri’s. A few things are worked out from those files rather than published directly — the average roof colour of a block, for one — and the catalogue linked at the foot of this page says which, field by field.',
  'us.sf.thecity.note.datasets': '{n} datasets',
  'us.sf.thecity.note.dataset_one': '{n} dataset',
  'us.sf.thecity.footer.perimeter': '{buildings} buildings, {blocks} assessor blocks, {streets} streets and {trees} street trees, drawn on the city’s own elevation data.',
  'us.sf.thecity.footer.coverage': '{decisions} decisions are placed on a block or on a street it fronts; {unplaced} name no place we could resolve and are not shown.',
