  'us.sf.contracts.how.auth.note': 'The register records a free-text purchasing authority on each contract; {n} distinct strings were grouped by hand into these {f} families ({method}, human review pending). Competitive bidding is the largest path by money. The rest are lawful alternatives the Administrative Code provides for — grant-making, agreements between public agencies, rents, emergencies, and sole-source waivers.',
  'us.sf.contracts.how.paid.h': 'When payments run past the agreed amount',
  'us.sf.contracts.how.paid.body': 'The agreed amount reflects the base document; payments accumulate across every later modification. So paid can exceed agreed without anything being wrong: <b>{nActive}</b> contracts active today have been paid <b>{over}</b> beyond their agreed amounts, and {nUni} of those are “Unilateral” construction contracts — the vehicle the register uses to book change orders in the first place.',
  'us.sf.contracts.how.sole.h': 'Awarded without competitive bidding',

