  'us.sf.contracts.money.noun.dept': 'departments',
  'us.sf.contracts.money.note.type': 'Grants the City gives out are the single biggest slice — this register covers every supplier agreement, not only procurement. {lbe} is committed to certified Local Business Enterprises as prime contractor and {np} contracts are held by nonprofits; both cut across the slices above and are never added to them.',
  'us.sf.contracts.money.note.supplier': 'No supplier dominates: the nine biggest hold {share} between them and the remaining {rest} suppliers hold the rest. The register carries no supplier identifier, so name variants are not merged.',
  'us.sf.contracts.money.note.dept': 'A department’s contracts and its budget are different registers and never add up: a contract is a multi-year commitment to a supplier, the budget is one year of appropriation across salaries, materials and everything else.',
  'us.sf.contracts.how.auth.kicker': 'Agreed by recorded legal basis · contracts running today',
