  'us.sf.contracts.how.stat.sole': 'agreed under the {n} contracts ({pct}% of the register) awarded without competitive bidding. {active} of them are running today.',
  'us.sf.contracts.money.pareto.type': 'The {n} biggest contract types hold {share} of the money committed today.',
