  'us.sf.contracts.s04.sub': 'San Francisco certifies Local Business Enterprises and tracks them on contract teams. Two different measures exist — as primes, and inside other primes’ teams.',
  'us.sf.contracts.s04.subtitle': 'Two measures: as primes, and inside other primes’ teams.',
  'us.sf.contracts.s04.prime.label': 'As prime contractors',
