  'us.sf.contracts.s04.team.sub': 'attached across {n} contracts · {rows} team entries',
  'us.sf.contracts.s04.never_sum': 'The two figures are different perimeters: team attachments live inside prime envelopes (and the register’s own sub-totals over-run the prime amount on some contracts). They are never added together.',

