  'us.sf.contracts.s05.sub': '{n} contracts active today. Search by supplier, title or theme.',
  'us.sf.contracts.s05.note': 'Agreed records the base document, not a ceiling: later modifications get paid without being added to it, so paid can exceed agreed — on {nActive} contracts running today, {n} across the register. All but {nRecon} of those also fail the register’s own arithmetic, so the gap measures its bookkeeping, not a payment.',

