  'us.sf.contracts.s07.m1': 'One row per contract: amounts are summed over the register’s prime-contractor rows ({nMulti} contracts carry two prime rows that net additive amendments); {nSubOnly} register entries have only subcontractor rows and are excluded from money totals.',
  'us.sf.contracts.s07.m2': 'The register’s own consumed/remaining columns fail basic arithmetic and are never published here. “Remaining” anywhere on this page is agreed minus paid, floored at zero.',
