  'us.sf.fy2018.title': 'One break to know about: fiscal year 2018.',
  'us.sf.fy2018.intro': 'In FY2018 the City moved its financial system to PeopleSoft. Several things change in the data at that point:',
  'us.sf.fy2018.b.accounts': 'The chart of accounts switched (numeric codes became mnemonics) and FY2018 itself mixes both systems, so this site shows citywide, service-area and fund totals for FY2018 but no department or category breakdown.',
  'us.sf.fy2018.b.programs': 'Program detail collapses: before 2018, hundreds of real per-department programs; from FY2019, ~10 generic activity tags (Operating, Capital, Administrative…).',
  'us.sf.fy2018.b.contracts': 'Contract numbers and nonprofit flags only begin in FY2018 — earlier payments can’t be tied to contracts or nonprofit status.',
  'us.sf.fy2018.b.vendors': 'Vendor-level granularity changes across the break — long payee series need care.',
  'us.sf.fy2018.consequence': 'A chart that kinks at 2018 reflects the system migration, not a change in policy. Department-level history is shown from FY2019 onward; service-area (organization group) history is comparable across the whole range.',

